using JasperFx.Events.Daemon;          // DaemonMode
using JasperFx.Events.Projections;     // ProjectionLifecycle
using Marten;
// SnapshotLifecycle is in Marten.Events.Projections while ProjectionLifecycle is in
// JasperFx.Events.Projections. Two enums for the same idea in two assemblies, and no doc page says which
// is where — settled by reflecting over both.
using Marten.Events.Projections;
using Campaigns.Views;

namespace Campaigns;

/// <summary>
/// THE ONE FILE WHERE THE READ-SIDE CHOICES ARE STATED. Five views, six recipes, and not one of them is
/// determined by the model — `Event(s) → View` says a read model is derived from those events and nothing
/// more. The generator scaffolded all five as single- or multi-stream projections registered Inline,
/// because that is all `identity=` narrows it to. Four of the five ended up somewhere else.
///
/// | view              | identity=            | recipe                                    | lifecycle |
/// |-------------------|----------------------|-------------------------------------------|-----------|
/// | MessageStatus     | messageId            | self-aggregating snapshot (also read LIVE)| Inline    |
/// | DeliveryLog       | messageId, recipient | EventProjection — one event, many rows    | Inline    |
/// | CampaignDashboard | campaignId           | MultiStream over TWO stream types         | **Async** |
/// | SenderMonthly     | senderId, month      | MultiStream over many streams of ONE type | Inline    |
/// | MessageMetrics    | messageId            | FlatTableProjection — a SQL table         | Inline    |
///
/// Nothing checks any of it. The model validates, this compiles, the tests pass, and a wrong choice here
/// is invisible. Which is why the table above exists.
/// </summary>
public static class ViewRegistrations
{
    public static void Register(StoreOptions opts)
    {
        // MessageStatus — RECIPE 1/2. Snapshot<T>, not Add<TProjection>: the folds live on the record
        // itself, so the same type is also readable live via AggregateStreamAsync with no registration at
        // all. Inline, so a write's effect is assertable the moment it returns.
        opts.Projections.Snapshot<MessageStatus>(SnapshotLifecycle.Inline);

        // DeliveryLog — RECIPE 3. An EventProjection is registered by INSTANCE, because its configuration
        // (DeleteViewTypeOnTeardown) lives in its constructor. Add<T>() would work too; the instance form
        // makes it obvious that construction matters.
        opts.Projections.Add(new DeliveryLogProjection(), ProjectionLifecycle.Inline);

        // CampaignDashboard — RECIPE 4, plus the lookup its grouper reads.
        //
        // THE LOOKUP'S LIFECYCLE IS LOAD-BEARING, and this was measured rather than reasoned. Inline means
        // its row is committed in the append's own transaction, so the mapping exists before the daemon
        // ever sees the page. Switched to Async, the grouper's DB query finds nothing for an outcome event
        // sharing a batch with its MessageQueued — and the event is silently dropped:
        //
        //   lookup Inline, batch scan on or off   -> counted
        //   lookup Async,  batch scan ON          -> counted
        //   lookup Async,  batch scan OFF         -> Delivered == 0, nothing thrown, nothing logged
        //
        // So the two protections are not redundant with each other, they are redundant HERE: Inline is what
        // makes this configuration safe, and the batch scan is what keeps it safe if anyone ever moves this
        // line to Async. Both kept deliberately — the failure mode is a counter that is quietly wrong.
        opts.Projections.Add<MessageCampaignLinkProjection>(ProjectionLifecycle.Inline);
        opts.Projections.Add<CampaignDashboardProjection>(ProjectionLifecycle.Async);

        // SenderMonthly — RECIPE 5. Inline against Marten's default of Async for multi-stream, so that one
        // project shows both costs. See the note in SenderMonthly.cs for why that is defensible here and
        // where it would not be.
        opts.Projections.Add<SenderMonthlyProjection>(ProjectionLifecycle.Inline);

        // MessageMetrics — RECIPE 6. A table, not a document. Registered exactly like any other
        // projection, which is the part worth noticing: the storage differs, the registration does not.
        opts.Projections.Add(new MessageMetricsProjection(), ProjectionLifecycle.Inline);
    }

    /// <summary>
    /// CampaignDashboard is Async, so the daemon is not optional. Without it that projection is never
    /// processed and Marten only logs a warning at startup — a read model that is permanently empty and
    /// nothing failing.
    ///
    /// Solo rather than HotCold: one node, no leader election, much faster startup.
    ///
    /// This hook exists because Program.cs is emit() and the daemon is registered on the Marten CHAIN, not
    /// on StoreOptions — so "Async" could not be chosen in a scaffold without it.
    /// </summary>
    public static void ConfigureStore(MartenServiceCollectionExtensions.MartenConfigurationExpression marten)
    {
        marten.AddAsyncDaemon(DaemonMode.Solo);
    }
}
